using System;using System.IO;using System.Collections;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;
internal static class AiNotificationPresentation {
 static Button Find(DependencyObject node,string prefix){var button=node as Button;if(button!=null&&Convert.ToString(button.Content).StartsWith(prefix))return button;foreach(object child in LogicalTreeHelper.GetChildren(node)){var next=child as DependencyObject;if(next!=null){var found=Find(next,prefix);if(found!=null)return found;}}return null;}
 [STAThread]static int Main(string[] args){try{bool opened=false;var card=SentinelAiNotification.Create("whatsapp_message","This prize message pressures you to act quickly. Verify the offer independently before following links or sharing information.",delegate{opened=true;});if(card.ShowActivated||!card.Topmost)throw new Exception("Notification activation changed.");if(Find(card,"Learn more")==null||Find(card,"×")==null)throw new Exception("Missing notification actions.");var root=(FrameworkElement)card.Content;root.Measure(new Size(card.Width,card.Height));root.Arrange(new Rect(0,0,card.Width,card.Height));root.UpdateLayout();var bitmap=new RenderTargetBitmap(792,476,192,192,PixelFormats.Pbgra32);bitmap.Render(root);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(args[0]))encoder.Save(output);Find(card,"Learn more").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));if(!opened)throw new Exception("Learn more did not reach its handler.");Console.WriteLine("Notification layout and Learn more handler passed; no live warning shown.");return 0;}catch(Exception e){Console.WriteLine(e.ToString());return 1;}}
}
